  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$, $j${"readings": [{"title": "Hebrews 4 (King James Version)", "url": "/portal/bible/Hebrews/4"}, {"title": "Hebrews 11 (King James Version)", "url": "/portal/bible/Hebrews/11"}, {"title": "Hebrews 12 (King James Version)", "url": "/portal/bible/Hebrews/12"}], "body": "Read Hebrews 4, Hebrews 11 and Hebrews 12 in the King James Version. Then read this lesson.\n\nThe book of Hebrews was written to Jewish believers who were tempted to go back to the old ways because of pressure and suffering. The writer is not named in the book. The message is that Jesus is better than everything that came before Him. He is greater than the angels, greater than Moses and greater than the priests of the old covenant. Hebrews 4 teaches that Jesus is our great high priest who understands our weakness, and that we may come boldly to the throne of grace. Hebrews 11 is often called the hall of faith, because it lists men and women who trusted God, such as Noah, Abraham and Moses. Hebrews 12 urges believers to run the race with patience, looking unto Jesus.\n\nKey words: high priest, throne of grace, faith, witnesses, patience.\n\nYour task: (1) Tell why Hebrews was written and what it says about Jesus. (2) Write Hebrews 11:1 in your own words. (3) Name two people from Hebrews 11 and tell what each one did by faith.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 5. In this unit we study the books that come after Paul's letters: Hebrews, James, First and Second Peter, the three letters of John, and Jude. These are often called the General Epistles, because most of them were written to believers everywhere and not to one church.\n\nWe begin with Hebrews. The first readers were Jewish believers who were under heavy pressure. Some were tempted to give up their faith in Jesus and go back to the old way of worship. The writer does not give his name, but he writes with great power. His message is that Jesus is better. Jesus is greater than the angels, greater than Moses, and greater than the priests who offered sacrifices in the temple.\n\nIn chapter 4 the writer speaks of the Word of God. Hebrews 4:12 says, For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart. Then he points to Jesus as our high priest. Hebrews 4:15 says, For we have not an high priest which cannot be touched with the feeling of our infirmities; but was in all points tempted like as we are, yet without sin. Because Jesus knows what we go through, verse 16 invites us, Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need.\n\nChapter 11 is one of the best known chapters in the Bible. Hebrews 11:1 says, Now faith is the substance of things hoped for, the evidence of things not seen. Verse 6 says, But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him. Then the writer lists people who trusted God. Noah built an ark when there was no rain. Verse 8 says, By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went. Moses chose to suffer with the people of God instead of enjoying the pleasures of sin for a season. Faith means believing God and acting on it even when we cannot see the end.\n\nChapter 12 begins with an encouragement. Hebrews 12:1 says, Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us, And the next verse tells us where to look. Hebrews 12:2 says, Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God. Jesus started our faith, and He will finish it.\n\nYour task is to tell why Hebrews was written, write Hebrews 11:1 in your own words, and name two people from Hebrews 11 and what they did by faith. Then take the four question check.\n\nJesus is better, and He is enough. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 James: Faith That Works$j$, $j${"readings": [{"title": "James 1 (King James Version)", "url": "/portal/bible/James/1"}, {"title": "James 2 (King James Version)", "url": "/portal/bible/James/2"}, {"title": "James 3 (King James Version)", "url": "/portal/bible/James/3"}, {"title": "James 4 (King James Version)", "url": "/portal/bible/James/4"}], "body": "Read James 1, James 2, James 3 and James 4 in the King James Version. Then read this lesson.\n\nThe letter of James was written by James, the brother of Jesus and a leader of the church in Jerusalem, to Jewish believers scattered abroad. It is a very practical book, and it is full of short commands. James taught that trials test our faith and produce patience, and that anyone who lacks wisdom may ask God. He taught that believers must be doers of the word and not hearers only. In chapter 2 he wrote that faith without works is dead, which means that real faith shows itself in action. In chapter 3 he warned about the power of the tongue, and in chapter 4 he urged believers to submit to God, resist the devil and humble themselves.\n\nKey words: trials, patience, wisdom, doers, tongue.\n\nYour task: (1) Tell who James was and who he wrote to. (2) Write James 1:22 in your own words. (3) Explain what James meant when he said that faith without works is dead.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Our next book is James, and it may be the most practical book in the New Testament. The writer is James, the brother of Jesus, who became a leader of the church in Jerusalem. At first James did not believe in Jesus during His earthly ministry, but after the resurrection he became a faithful servant. He wrote this letter to Jewish believers who were scattered and facing hard times.\n\nJames begins with trials. James 1:2 says, My brethren, count it all joy when ye fall into divers temptations; The word temptations here means trials. Verse 3 says, Knowing this, that the trying of your faith worketh patience. And verse 4 says, But let patience have her perfect work, that ye may be perfect and entire, wanting nothing. God uses hard times to grow us. James also gave an invitation in verse 5, If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him. Students, if you need wisdom for a test, a friendship or a decision, you can ask God.\n\nThen James gave a key command. James 1:22 says, But be ye doers of the word, and not hearers only, deceiving your own selves. It is not enough to listen to a sermon or read a Bible verse. We must do what it says.\n\nIn chapter 2 James explained that real faith shows itself in action. James 2:14 says, What doth it profit, my brethren, though a man say he hath faith, and have not works? can faith save him? He did not say that works save us. Paul had already made clear that we are saved by grace through faith. James said that true faith produces good works, just as a living body shows signs of life. James 2:26 says, For as the body without the spirit is dead, so faith without works is dead also. Paul and James do not disagree. Paul teaches how we are saved, and James teaches what saving faith looks like.\n\nChapter 3 is about the tongue. James 3:5 says, Even so the tongue is a little member, and boasteth great things. Behold, how great a matter a little fire kindleth! A few careless words can hurt many people, so we must guard our speech.\n\nChapter 4 ends with a call to draw near to God. James 4:7 says, Submit yourselves therefore to God. Resist the devil, and he will flee from you. Verse 8 says, Draw nigh to God, and he will draw nigh to you. And verse 10 says, Humble yourselves in the sight of the Lord, and he shall lift you up.\n\nYour task is to tell who James was and who he wrote to, write James 1:22 in your own words, and explain what James meant when he said that faith without works is dead. Then take the four question check.\n\nReal faith is a faith that lives, and it shows in what we do. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 James: Faith That Works$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 First and Second Peter: Hope in Suffering$j$, $j${"readings": [{"title": "1 Peter 1 (King James Version)", "url": "/portal/bible/1Peter/1"}, {"title": "1 Peter 2 (King James Version)", "url": "/portal/bible/1Peter/2"}, {"title": "1 Peter 5 (King James Version)", "url": "/portal/bible/1Peter/5"}, {"title": "2 Peter 3 (King James Version)", "url": "/portal/bible/2Peter/3"}], "body": "Read 1 Peter 1, 1 Peter 2, 1 Peter 5 and 2 Peter 3 in the King James Version. Then read this lesson.\n\nThe apostle Peter wrote two letters near the end of his life. First Peter was written to believers scattered across Asia Minor who were suffering for their faith. Peter encouraged them with a living hope through the resurrection of Jesus Christ. He taught that the trial of their faith is more precious than gold, that they are a chosen generation and a royal priesthood, and that Christ left them an example to follow. In chapter 5 he told them to humble themselves, to cast all their care on God because He cares for them, and to be sober and watchful against the devil. Second Peter was written to warn about false teachers and to remind believers that the Lord is patient and wants all to come to repentance. Peter ended by urging them to grow in grace and in the knowledge of Jesus Christ.\n\nKey words: living hope, trial, royal priesthood, care, grow.\n\nYour task: (1) Tell why Peter wrote his first letter. (2) Write 1 Peter 5:7 in your own words. (3) Explain what Peter meant when he said the Lord is longsuffering in 2 Peter 3.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The apostle Peter wrote the next two letters. You will remember Peter from the Gospels and Acts. He was the fisherman who denied Jesus three times, was forgiven and restored, preached at Pentecost, and became a leader of the early church. Near the end of his life he wrote letters to strengthen other believers.\n\nFirst Peter was written to Christians scattered across Asia Minor who were suffering for their faith. Peter began with praise. First Peter 1:3 says, Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead, A lively hope means a living hope. It is alive because Jesus is alive. Peter then explained that trials have a purpose. First Peter 1:7 says, That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ: Gold is refined in fire, and our faith is made stronger in trials.\n\nPeter also called believers to live holy lives. First Peter 1:16 says, Because it is written, Be ye holy; for I am holy. And in chapter 2 he reminded them who they are. First Peter 2:9 says, But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light: Peter pointed to Jesus as our example in verse 21, For even hereunto were ye called: because Christ also suffered for us, leaving us an example, that ye should follow his steps:\n\nIn chapter 5 Peter gave advice that every student needs. First Peter 5:6 says, Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time: And verse 7 says, Casting all your care upon him; for he careth for you. We do not have to carry our worries alone. Then verse 8 warns, Be sober, be vigilant; because your adversary the devil, as a roaring lion, walketh about, seeking whom he may devour: We must stay alert.\n\nSecond Peter was written shortly before Peter died. False teachers were appearing in the church, and some people were mocking the promise of the Lord's return. Peter answered in 2 Peter 3:8, But, beloved, be not ignorant of this one thing, that one day is with the Lord as a thousand years, and a thousand years as one day. God is not slow. He is patient, because He wants everyone to have time to repent. Peter closed with these words in 2 Peter 3:18, But grow in grace, and in the knowledge of our Lord and Saviour Jesus Christ. To him be glory both now and for ever. Amen.\n\nYour task is to tell why Peter wrote his first letter, write 1 Peter 5:7 in your own words, and explain what Peter meant when he said the Lord is patient. Then take the four question check.\n\nCast your care on Him, and keep growing. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 First and Second Peter: Hope in Suffering$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 The Letters of John and Jude$j$, $j${"readings": [{"title": "1 John 1 (King James Version)", "url": "/portal/bible/1John/1"}, {"title": "1 John 4 (King James Version)", "url": "/portal/bible/1John/4"}, {"title": "1 John 5 (King James Version)", "url": "/portal/bible/1John/5"}, {"title": "3 John 1 (King James Version)", "url": "/portal/bible/3John/1"}, {"title": "Jude 1 (King James Version)", "url": "/portal/bible/Jude/1"}], "body": "Read 1 John 1, 1 John 4, 1 John 5 and Jude 1 in the King James Version. Then read this lesson.\n\nThe apostle John, who wrote the Gospel of John, also wrote three short letters, probably when he was an old man. First John was written to help believers be sure that they have eternal life. John taught that if we walk in the light we have fellowship with one another and the blood of Jesus cleanses us from all sin, and that if we confess our sins God is faithful and just to forgive us. In chapter 4 he wrote that God is love and that we love Him because He first loved us. Second John and Third John are very short personal letters about walking in truth and showing kindness. Jude was probably written by the brother of Jesus and James. Jude urged believers to contend earnestly for the faith once delivered to the saints and ended with a beautiful blessing to the God who is able to keep us from falling.\n\nKey words: light, confess, love, victory, contend.\n\nYour task: (1) Tell why John wrote 1 John. (2) Write 1 John 1:9 in your own words. (3) Explain what Jude meant by contending for the faith.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we finish our study of the letters with the writings of John and Jude. The apostle John was one of the first disciples, and he wrote the Gospel of John, three short letters and the book of Revelation. He wrote his letters when he was very old, and he wrote like a loving father speaking to his children.\n\nFirst John was written so that believers could be sure of their salvation. Some false teachers were saying that Jesus had not really come in the flesh, and John answered with what he had seen with his own eyes. First John 1:7 says, But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin. Then verse 9 gives a promise for every one of us. If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness. When we fall, we do not have to hide. We can confess, and God forgives.\n\nLove is a major theme of this letter. First John 4:7 says, Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God. Verse 8 says, He that loveth not knoweth not God; for God is love. John showed us where love begins. In verse 10 he wrote, Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins. And verse 19 says, We love him, because he first loved us. We can love others because He loved us first.\n\nFirst John also gives victory and assurance. First John 5:4 says, For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith. And verse 13 says, These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God.\n\nSecond John and Third John are very short. Second John 1:6 says, And this is love, that we walk after his commandments. This is the commandment, That, as ye have heard from the beginning, ye should walk in it. Third John was written to a faithful friend named Gaius. Third John 1:4 says, I have no greater joy than to hear that my children walk in truth.\n\nThe last of the General Epistles is Jude, a short and urgent letter. Jude was a brother of Jesus and of James. He wanted to write about salvation, but he felt he had to warn the church about false teachers. Jude 1:3 says, Beloved, when I gave all diligence to write unto you of the common salvation, it was needful for me to write unto you, and exhort you that ye should earnestly contend for the faith which was once delivered unto the saints. To contend for the faith means to hold firmly to the truth of the gospel and defend it. Jude closed with a blessing. Jude 1:24 says, Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy, And verse 25 says, To the only wise God our Saviour, be glory and majesty, dominion and power, both now and ever. Amen.\n\nYour task is to tell why John wrote First John, write 1 John 1:9 in your own words, and explain what Jude meant by contending for the faith. Then take the four question check and the Unit 5 quiz.\n\nGod is love, and He is able to keep us. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 The Letters of John and Jude$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Faith in Action$j$, $j${"prompt": "Choose one verse from this unit: Hebrews 11:1, Hebrews 12:2, James 1:22, James 2:26, 1 Peter 5:7, 2 Peter 3:18, 1 John 1:9 or 1 John 4:19. Write one paragraph of 150 to 200 words. Quote the verse from the King James Version with the reference, explain what it meant to the first readers, and tell how a student today can put it into action this week.", "rubric": "Total 100. Accurate quotation of the verse with the reference: 20. Explains the meaning for the first readers: 30. Gives a clear and realistic application for this week: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Faith in Action$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Faith, Trials and Love$j$, $j${"prompt": "The letters in this unit teach us to keep believing during trials and to show love in practical ways. Think about a trial a young person might face. Tell which teaching from Hebrews, James, Peter or John would help most and why. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Faith, Trials and Love$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$, $j${"questions": [{"q": "What is the main message of the book of Hebrews?", "options": ["Angels are greater than Jesus", "The temple will be rebuilt", "Believers must keep the old sacrifices", "Jesus is better than everything that came before"]}, {"q": "According to Hebrews 4:16, where may believers come boldly?", "options": ["To the mountain of Moses", "To the throne of grace", "To the temple in Jerusalem", "To the city gates"]}, {"q": "According to Hebrews 11:1, what is faith?", "options": ["A good feeling", "The substance of things hoped for, the evidence of things not seen", "A reward for good works", "A kind of luck"]}, {"q": "According to Hebrews 12:2, who are we to look unto?", "options": ["Jesus, the author and finisher of our faith", "The prophets", "The law", "The angels"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,0}'::int[], array[$j$Hebrews shows that Jesus is greater than the angels, Moses and the priests.$j$,$j$We may come boldly to the throne of grace to obtain mercy and find grace to help.$j$,$j$Hebrews 11:1 defines faith as the substance of things hoped for, the evidence of things not seen.$j$,$j$Hebrews 12:2 tells us to look unto Jesus the author and finisher of our faith.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: James: Faith That Works$j$, $j${"questions": [{"q": "Who wrote the letter of James?", "options": ["James the son of Zebedee", "James, the brother of Jesus and a leader in Jerusalem", "Peter", "Paul"]}, {"q": "According to James 1:3, what does the trying of your faith work?", "options": ["Pride", "Wealth", "Fear", "Patience"]}, {"q": "What does James 1:22 tell believers to be?", "options": ["Teachers of the law", "Silent in the church", "Hearers only", "Doers of the word"]}, {"q": "According to James 2:26, what is faith without works?", "options": ["Dead", "Hidden", "Strong", "Complete"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: James: Faith That Works$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,0}'::int[], array[$j$The letter was written by James, the brother of Jesus and leader of the church in Jerusalem.$j$,$j$James 1:3 says the trying of your faith worketh patience.$j$,$j$James 1:22 says to be doers of the word and not hearers only.$j$,$j$James 2:26 says faith without works is dead also.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: James: Faith That Works$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: First and Second Peter: Hope in Suffering$j$, $j${"questions": [{"q": "To whom did Peter write his first letter?", "options": ["The priests in the temple", "Kings and rulers", "Believers scattered across Asia Minor who were suffering", "The church at Rome"]}, {"q": "According to 1 Peter 1:7, the trial of your faith is more precious than what?", "options": ["Land", "Fine linen", "Silver", "Gold that perisheth"]}, {"q": "What does 1 Peter 5:7 tell believers to cast upon the Lord?", "options": ["All their care", "Their nets", "Their crowns", "Their garments"]}, {"q": "What does 2 Peter 3:18 tell believers to do?", "options": ["Build a temple", "Grow in grace and in the knowledge of our Lord and Saviour Jesus Christ", "Return to the old law", "Stop gathering"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: First and Second Peter: Hope in Suffering$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,1}'::int[], array[$j$First Peter was written to scattered believers who suffered for their faith.$j$,$j$Peter said the trial of faith is much more precious than gold that perisheth.$j$,$j$Peter wrote, Casting all your care upon him; for he careth for you.$j$,$j$Peter ended his letter by urging believers to grow in grace and knowledge.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: First and Second Peter: Hope in Suffering$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: The Letters of John and Jude$j$, $j${"questions": [{"q": "According to 1 John 1:9, what will God do if we confess our sins?", "options": ["He will test us again", "He will ask us to pay", "He will forgive us and cleanse us from all unrighteousness", "He will ignore us"]}, {"q": "According to 1 John 4:8, what is God?", "options": ["Love", "King", "Judge", "Rock"]}, {"q": "Why does 1 John 4:19 say we love Him?", "options": ["Because we are strong", "Because He first loved us", "Because we are good", "Because we are wise"]}, {"q": "What did Jude urge believers to do in Jude 1:3?", "options": ["Keep silent", "Leave the church", "Earnestly contend for the faith which was once delivered unto the saints", "Rebuild the temple"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Letters of John and Jude$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,2}'::int[], array[$j$First John 1:9 says God is faithful and just to forgive us our sins and cleanse us.$j$,$j$First John 4:8 says, God is love.$j$,$j$We love Him because He first loved us.$j$,$j$Jude urged believers to hold firmly to the faith once delivered to the saints.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Letters of John and Jude$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Hebrews and the General Epistles$j$, $j${"questions": [{"q": "What does Hebrews 4:16 invite believers to come to?", "options": ["The throne of grace", "The gates of Jerusalem", "The mountain", "The ark"]}, {"q": "Which chapter of Hebrews is often called the hall of faith?", "options": ["Chapter 1", "Chapter 11", "Chapter 13", "Chapter 4"]}, {"q": "What does James 1:22 say believers should be?", "options": ["Teachers only", "Doers of the word, and not hearers only", "Hearers only", "Silent in the church"]}, {"q": "According to 1 Peter 5:7, why can believers cast all their care on God?", "options": ["Because He is far away", "Because troubles do not matter", "Because He does not know", "Because He careth for you"]}, {"q": "According to 1 John 4:8, what is God?", "options": ["Silence", "Love", "Law", "Wrath"]}, {"q": "What does Jude 1:24 say God is able to do?", "options": ["Keep us from falling", "End the world", "Remove all trials", "Rebuild the temple"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Hebrews and the General Epistles$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3,1,0}'::int[], array[$j$We may come boldly unto the throne of grace to find mercy and help.$j$,$j$Hebrews 11 lists men and women who trusted God.$j$,$j$James 1:22 teaches that we must act on God's word.$j$,$j$Peter wrote, Casting all your care upon him; for he careth for you.$j$,$j$First John 4:8 says, God is love.$j$,$j$Jude ends with praise to God who is able to keep us from falling.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Hebrews and the General Epistles$j$ on conflict (item_id) do nothing;
